import json
import os
import pickle

import numpy as np

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

# Global variables to store model info
best_model = None
model_name = ""
model_type = ""

@app.on_event("startup")
def load_model_at_startup():
    global best_model, model_name, model_type
    with open('/app/models/best_model.pkl', 'rb') as f:
        best_model = pickle.load(f)
    # Determine model name and type from the loaded model's class
    model_class_name = best_model.__class__.__name__
    if model_class_name == "RandomForestRegressor":
        model_name = "random_forest"
        model_type = "RandomForestRegressor"
    elif model_class_name == "Ridge":
        model_name = "ridge"
        model_type = "Ridge"
    elif model_class_name == "LinearRegression":
        model_name = "linear_regression"
        model_type = "LinearRegression"
    else:
        model_name = model_class_name
        model_type = model_class_name

# Pydantic models for request/response
class PredictRequest(BaseModel):
    features: list

class PredictBatchRequest(BaseModel):
    features_list: list

class PredictResponse(BaseModel):
    prediction: float
    model_name: str

class HealthResponse(BaseModel):
    status: str
    model_loaded: bool

class ModelInfoResponse(BaseModel):
    model_name: str
    model_type: str
    features_count: int

class PredictBatchResponse(BaseModel):
    predictions: list
    model_name: str
    count: int

@app.post("/predict")
def predict(request: PredictRequest):
    # request.features is a list of floats
    features_array = np.array(request.features).reshape(1, -1)  # Make it 1 sample x 8 features
    prediction = best_model.predict(features_array)[0]
    return {"prediction": prediction, "model_name": model_name}

@app.get("/health")
def health():
    return {"status": "healthy", "model_loaded": True}

@app.get("/model-info")
def model_info():
    return {
        "model_name": model_name,
        "model_type": model_type,
        "features_count": 8
    }

@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest):
    features_list = request.features_list
    predictions = []
    for features in features_list:
        features_array = np.array(features).reshape(1, -1)  # Make it 1 sample x 8 features
        pred = best_model.predict(features_array)[0]
        predictions.append(pred)
    return {
        "predictions": predictions,
        "model_name": model_name,
        "count": len(predictions)
    }
